import mongoose from 'mongoose';

const generatedDeckSchema = new mongoose.Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      required: true,
      ref: 'User',
      index: true,
    },
    deckId: {
      type: String,
      required: true,
      index: true,
    },
    title: {
      type: String,
      required: true,
      trim: true,
    },
    // Store the full deck payload as generated by /api/generate
    deck: {
      type: mongoose.Schema.Types.Mixed,
      required: true,
    },
    // Optional linkage to uploaded file/topic when available
    topicId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Topic',
    },
    r2Key: {
      type: String,
    },
    createdAt: {
      type: Date,
      default: Date.now,
      index: true,
    },
  },
  { collection: 'generatedDecks', timestamps: false }
);

export const GeneratedDeck =
  mongoose.models.GeneratedDeck || mongoose.model('GeneratedDeck', generatedDeckSchema);
